// Pure, versioned report helpers. No browser instrumentation or media contents.
export const SCHEMA_VERSION='1.0.0';
export const LIMITS={samples:2048,events:1200,runs:12,resources:512};
export const metric=(value,unit,method,status='observed',sampleCount=1)=>({value,unit,method,status,sampleCount});
export function series(){return{count:0,total:0,max:null,samples:[]}}
export function add(s,value){if(!Number.isFinite(value))return;s.count++;s.total+=value;s.max=s.max===null?value:Math.max(s.max,value);if(s.samples.length<LIMITS.samples)s.samples.push(value);else s.samples[(s.count-1)%LIMITS.samples]=value}
export function stats(s,unit='ms',method='performance.now synchronous inclusive interval'){
 if(!s?.count)return{...metric(null,unit,method,'not_measured',0),total:null,mean:null,p50:null,p95:null,p99:null,max:null,retainedSampleCount:0};
 const a=[...s.samples].sort((a,b)=>a-b),q=p=>a[Math.min(a.length-1,Math.ceil(a.length*p)-1)];
 return{...metric(s.total/s.count,unit,method,'observed',s.count),count:s.count,total:s.total,mean:s.total/s.count,p50:q(.5),p95:q(.95),p99:q(.99),max:s.max,retainedSampleCount:a.length,percentilePopulation:s.count>a.length?'bounded recent samples':'all samples'};
}
const numeric=value=>value!==null&&value!==undefined&&Number.isFinite(+value)?+value:null;
// Deliberate whitelist: never serialize a project, filename, caption, URL or path.
const fields=(o,keys)=>Object.fromEntries(keys.map(k=>[k,typeof o?.[k]==='boolean'?o[k]:numeric(o?.[k])]));
const points=a=>(a||[]).slice(0,256).map(p=>fields(p,['time','value','valueDb','x','y','scale']));
const color=c=>Object.fromEntries(Object.entries(c||{}).filter(([k,v])=>['exposure','brilliance','highlights','shadows','contrast','brightness','blackPoint','whites','blacks','gamma','temperature','warmth','tint','saturation','vibrance','fade','sharpness','definition','noiseReduction','vignette','curveMaster','curveRed','curveGreen','curveBlue',...['Shadow','Midtone','Highlight'].flatMap(z=>['Hue','Saturation','Lightness'].map(x=>'balance'+z+x))].includes(k)&&(typeof v==='number'||Array.isArray(v))).map(([k,v])=>[k,Array.isArray(v)?v.slice(0,16).map(p=>Array.isArray(p)?p.map(numeric):numeric(p)):v]));
const safeEnum=(value,allowed)=>allowed.includes(value)?value:'unknown';
export function projectProfile(p={}){
 const media=(p.media||[]).slice(0,2000),idMap=new Map(media.map((m,i)=>[m.id,'media-'+(i+1)]));
 const audio=a=>({...fields(a,['volume','mute','fadeIn','fadeOut','delayEnabled','delayTime','delayFeedback','delayMix']),gain:points(a?.gainKeyframes),envelope:points(a?.gainEnvelope)});
 const clips=(p.clips||[]).slice(0,2000).map(c=>({media:idMap.get(c.media)||null,...fields(c,['start','layer','in','out','speed','endSpeed','hold','gap','freezeAt','freezeDuration','opacity','fadeIn','fadeOut','scale','x','y','offsetX','offsetY','lookAmount','motionAmount']),timingBase:c.timingBase?{...fields(c.timingBase,['in','out','speed','endSpeed']),curve:safeEnum(c.timingBase.curve,['constant','ease-in','ease-out','ease-in-out'])}:null,curve:safeEnum(c.curve,['constant','ease-in','ease-out','ease-in-out']),motion:safeEnum(c.motionPreset,['none','push-in','pull-out','pan-left','pan-right','pan-up','pan-down']),stabilization:safeEnum(c.stabilization,['OFF','WEAK','MEDIUM','STRONG','HANDHELD','NATURAL','GIMBAL','HORIZON','TRIPOD','AGGRESSIVE']),interpolation:safeEnum(c.interpolation,['duplicate','blend','motion','motion-max']),transition:{type:safeEnum(c.transition?.type,['none','dissolve','slide','wipe','circle']),duration:numeric(c.transition?.duration),direction:safeEnum(c.transition?.direction,['left','right','up','down'])},color:color(c.color),opacityKeys:points(c.opacityKeyframes),scaleKeys:points(c.scaleKeyframes),audio:audio(c.audio)}));
 const effects=(p.effects||[]).slice(0,100).map(e=>({...fields(e,['start','duration','layer','strength','zoomX','zoomY','zoomSize','zoomIn','zoomOut','zoomReturn','returnAt','zoomTexts']),type:safeEnum(e.type,['flash','black-in','black-out','region-zoom']),motionKind:safeEnum(e.motionKind,['focus','face-follow','camera-bump','audio-pulse']),trackPath:points(e.trackPath),motionPath:points(e.motionPath)}));
 const texts=(p.texts||[]).slice(0,300).map(t=>({...fields(t,['start','end','layer','size','x','y','opacity','fade','fadeIn','fadeOut','outline','outerOutline','shadow','shadowBlur','shadowX','shadowY','letterSpacing','weight','lineHeight','motionDuration','motionStart','motionEnd','motionScaleFrom','motionScaleTo']),characters:String(t.text||'').length,lines:String(t.text||'').split('\n').length,motion:safeEnum(t.motion,['none','rise','slide-left','pop','scale'])}));
 return{media:media.map((m,i)=>({id:'media-'+(i+1),...fields(m,['width','height','fps','duration','size','hdr','audio']),kind:safeEnum(m.kind||(m.width&&m.height?'video':'audio'),['image','video','audio']),codec:safeEnum(String(m.codec||'').toLowerCase(),['avc','h264','h.264','hevc','h265','h.265','aac','mp3','pcm','prores','vp9','av1','image/png','image/jpeg'])})),clips,effects,texts,audioClips:(p.audioClips||[]).slice(0,200).map(c=>({media:idMap.get(c.media)||null,...fields(c,['start','layer','in','out','speed','endSpeed','loop']),audio:audio(c.audio)})),bgm:{media:idMap.get(p.bgm?.media)||null,...audio(p.bgm)},videoTracks:(p.videoTracks||[]).map(t=>fields(t,['hidden','volume'])),audioTracks:(p.audioTracks||[]).map(t=>fields(t,['mute','solo','volume'])),overlayTracks:(p.overlayTracks||[]).map(t=>fields(t,['hidden'])),aspect:safeEnum(p.aspect,['Original','9:16','16:9','1:1','4:5']),identity:'anonymous metadata and settings only; does not prove identical source bytes or caption/font content'};
}
export const limitations=[
 'Canvas draw completion is JavaScript submission completion, not physical display presentation.',
 'requestVideoFrameCallback observes video-element frame submission to the compositor, not the final composited screen.',
 'CPU spans are inclusive and overlapping; never sum parent and child totals as total CPU time.',
 'API-estimated RGBA bytes are not measured bus traffic or GPU memory.',
 'Video element counts are not hardware decoder counts; browser decode duration and total RAM are unavailable.',
 'Instrumentation changes timing. Modes and timer-query settings must match for comparisons.',
 'Bounded recent samples determine percentiles after the sample cap; exact counts/totals/max remain streaming.',
 'Anonymous metadata cannot prove identical source bytes, caption glyphs, fonts, thermal state or background load.'
];
export function markdown(r){
 const p=r.playbackMetrics,c=r.cpuMetrics||{},gpu=r.gpuMetrics;
 return`# PVE Performance Diagnostics\n\n- Schema: ${r.schemaVersion}; PVE: ${r.appVersion}; commit: ${r.buildCommit||'not_measured'}\n- Scenario: ${r.scenario}; mode: ${r.measurementConfig.mode}; duration: ${r.measurementConfig.elapsedMs?.toFixed(1)} ms\n- Draw submissions: ${p.drawCompletions.value}; rate: ${p.drawSubmissionRate.value?.toFixed(2)??'not_measured'} Hz (not present FPS)\n- Draw interval p50/p95/p99: ${['p50','p95','p99'].map(k=>p.drawIntervals[k]?.toFixed(2)??'not_measured').join(' / ')} ms\n- Deadline exceedances: ${p.deadlineExceedances.value}; long stalls: ${p.longStalls.value}\n- Holds: ${p.holdCount.value}; observed duration: ${p.holdDuration.value?.toFixed(2)??'not_measured'} ms\n- GPU: ${gpu.duration.status}; texture upload calls: ${gpu.textureUploads.value}; estimated bytes: ${gpu.estimatedUploadBytes.value}\n\n## CPU inclusive intervals (do not add parent and child)\n\n| Span | Calls | Mean ms | p95 ms | Max ms |\n|---|---:|---:|---:|---:|\n${Object.entries(c).map(([k,v])=>`| ${k} | ${v.sampleCount} | ${v.mean?.toFixed(3)??'—'} | ${v.p95?.toFixed(3)??'—'} | ${v.max?.toFixed(3)??'—'} |`).join('\n')}\n\n## Warnings / unavailable\n\n${[...r.warnings,...r.measurementLimitations].map(x=>'- '+x).join('\n')}\n\nNumbers identify candidates, not proof of a causal bottleneck or memory leak.\n`;
}
export function reportValue(o,path){if(path.startsWith('cpuMetrics.')){const rest=path.slice(11);if(rest in (o.cpuMetrics||{}))return o.cpuMetrics[rest];const at=rest.lastIndexOf('.');return o.cpuMetrics?.[rest.slice(0,at)]?.[rest.slice(at+1)]}return path.split('.').reduce((v,k)=>v?.[k],o)}
const comparableKeys=['environment','capabilities','projectProfile','scenario'];
export function compareReports(a,b,{threshold=.05}={}){
 const warnings=[];if(a.schemaVersion?.split('.')[0]!==b.schemaVersion?.split('.')[0])warnings.push('schema major version differs');
 if(JSON.stringify(a.playbackMetrics?.effectiveResolutions)!==JSON.stringify(b.playbackMetrics?.effectiveResolutions))warnings.push('effective preview resolutions differ');
 for(const k of comparableKeys)if(JSON.stringify(a[k])!==JSON.stringify(b[k]))warnings.push(k+' differs');
 for(const k of ['mode','start','end','warmup','gpuTiming','repeatGroup','sampleLimit'])if(a.measurementConfig[k]!==b.measurementConfig[k])warnings.push('measurementConfig.'+k+' differs');
 if(a.measurementConfig.finishedRange!==true||b.measurementConfig.finishedRange!==true)warnings.push('requested range was not completed');
 const paths=['playbackMetrics.drawIntervals.p95','playbackMetrics.deadlineExceedances.value','playbackMetrics.holdDuration.value','playbackMetrics.seekLatency.p95','gpuMetrics.duration.p95','gpuMetrics.textureUploads.value','gpuMetrics.repeatedUploads.value','gpuMetrics.staticTextRedraws.value','gpuMetrics.shaderDraws.value','gpuMetrics.estimatedUploadBytes.value','memoryMetrics.resources.canvases','memoryMetrics.resources.textures'];
 for(const key of new Set([...Object.keys(a.cpuMetrics||{}),...Object.keys(b.cpuMetrics||{})]))paths.push('cpuMetrics.'+key+((a.cpuMetrics?.[key]||b.cpuMetrics?.[key])?.unit==='count'?'.value':'.mean'));
 const get=reportValue,rows=paths.map(path=>{const x=get(a,path),y=get(b,path),parentPath=path.split('.').slice(0,-1).join('.'),ma=get(a,parentPath),mb=get(b,parentPath);let reason=null;if(warnings.length)reason='conditions differ';else if(ma?.status==='estimated'||mb?.status==='estimated')reason='estimated';else if(ma?.status&&ma.status!=='observed'||mb?.status&&mb.status!=='observed')reason='not observed';else if(!Number.isFinite(x)||!Number.isFinite(y))reason='missing';else if(!(x>0))reason='zero baseline';const delta=reason?null:(y-x)/x;return{path,before:x??null,after:y??null,changePercent:delta===null?null:delta*100,assessment:'判断保留',reason:reason||'single-pair difference; verify repeat variability'};});
 return{comparable:!warnings.length,warnings:[...warnings,'Single runs cannot establish significance. Compare at least three repeats; small changes are inconclusive.'],rows};
}
export function comparisonMarkdown(c){return`# PVE performance comparison\n\n${c.comparable?'Comparable recorded conditions (source identity must be confirmed separately).':'条件差あり：改善率を表示しません。'}\n\n${c.warnings.map(x=>'- '+x).join('\n')}\n\n| Metric | Before | After | Change % | Assessment | Reason |\n|---|---:|---:|---:|---|---|\n${c.rows.map(r=>`| ${r.path} | ${r.before??'—'} | ${r.after??'—'} | ${r.changePercent?.toFixed(2)??'—'} | ${r.assessment} | ${r.reason} |`).join('\n')}\n`;}
export function compareRuns(before,after){
 const a=Array.isArray(before)?before:before.runs||[before],b=Array.isArray(after)?after:after.runs||[after];if(!a.length||!b.length)throw Error('Both inputs require at least one report');
 const result=compareReports(a[0],b[0]);for(const group of [a,b])for(const report of group.slice(1)){const c=compareReports(group[0],report);for(const w of c.warnings)if(w!=='Single runs cannot establish significance. Compare at least three repeats; small changes are inconclusive.'&&!result.warnings.includes(w))result.warnings.push(w);if(!c.comparable)result.comparable=false}
 const get=reportValue,range=values=>{const s=values.sort((a,b)=>a-b);return{median:s[Math.floor(s.length/2)],min:s[0],max:s.at(-1)}};
 for(const row of result.rows){const av=a.map(r=>get(r,row.path)),bv=b.map(r=>get(r,row.path));if(av.some(v=>!Number.isFinite(v))||bv.some(v=>!Number.isFinite(v)))continue;const x=range(av),y=range(bv);row.before=x.median;row.after=y.median;row.beforeRange=x;row.afterRange=y;if(!result.comparable){row.changePercent=null;row.assessment='判断保留';row.reason='conditions differ';continue}if(row.reason==='estimated'||row.reason==='not observed'||x.median<=0){row.changePercent=null;continue}row.changePercent=(y.median-x.median)/x.median*100;if(a.length<3||b.length<3||Math.abs(row.changePercent)<=5||x.min<=y.max&&y.min<=x.max){row.assessment='判断保留';row.reason='fewer than 3 repeats, <=5% change or repeat ranges overlap'}else{row.assessment=y.median<x.median?'改善':'悪化';row.reason='>=3 repeats; >5% median difference; non-overlapping observed ranges (not a significance test)'}}
 return result;
}
